export function SurfaceCard({ title, children, locked }: { title: string; children: React.ReactNode; locked?: boolean }) {
  return (
    <section
      className={`inscribed-frame px-5 py-5 transition-opacity duration-slow ease-gravity ${
        locked ? "border-gold-dim/40 bg-ink/25 text-gold-dim opacity-65" : "border-gold/35 bg-parchment/35"
      }`}
    >
      <h3 className="font-display text-lg tracking-[0.06em] text-gold-light">{title}</h3>
      <div className="mt-3 leading-[1.85] text-base">{children}</div>
    </section>
  );
}

